options.customCss:
:root{--hc-bg:#faf6f0;--hc-card:#fffcf8;--hc-card2:#f3eadf;--hc-line:#dfd1bf;--hc-txt:#382c22;--hc-muted:#6f5f51;--hc-accent:#8b5e3c}
body{background:radial-gradient(1200px 600px at 80% -10%,#f1e3d3 0%,transparent 60%),radial-gradient(900px 500px at -10% 110%,#eaddce 0%,transparent 55%),var(--hc-bg) !important;color:var(--hc-txt) !important}
.card{background:linear-gradient(180deg,var(--hc-card2),var(--hc-card)) !important;border:1px solid var(--hc-line) !important;border-radius:16px !important;box-shadow:0 8px 24px rgba(56,44,34,.12) !important}
.form-header h1{color:var(--hc-txt) !important;font-weight:700 !important}
.form-header p{color:var(--hc-muted) !important}
.form-label,label{color:var(--hc-txt) !important;font-weight:600 !important}
.form-input,.select-input,input,select,textarea{background:var(--hc-card) !important;border:1px solid var(--hc-line) !important;color:var(--hc-txt) !important;border-radius:10px !important}
.form-input:focus,.select-input:focus,input:focus,select:focus,textarea:focus{border-color:var(--hc-accent) !important;outline:none !important;box-shadow:0 0 0 3px rgba(139,94,60,.16) !important}
.form-input::placeholder,input::placeholder{color:var(--hc-muted) !important;opacity:.75}
#submit-btn{background:var(--hc-accent) !important;border:none !important;color:#fffcf8 !important;font-weight:700 !important;border-radius:10px !important;box-shadow:0 4px 12px rgba(56,44,34,.18) !important}
#submit-btn:hover{filter:brightness(1.08)}
.n8n-link,.n8n-link a,.n8n-link p{color:var(--hc-muted) !important}
#submitted-header{color:var(--hc-txt) !important}
#submitted-content{color:var(--hc-muted) !important}
.form-group.html a{display:inline-flex;align-items:center;gap:6px;padding:8px 14px;border-radius:10px;background:linear-gradient(180deg,var(--hc-card2),var(--hc-card));border:1px solid var(--hc-line);color:var(--hc-accent) !important;text-decoration:none !important;font-size:14px;font-weight:600}
.form-group.html a:hover{border-color:var(--hc-accent);background:var(--hc-card2)}

