const f=$('Prep').first().json;
const extra=f.source?{'แหล่ง':{select:{name:f.source}}}:{};
return [{json:{
  parent:{database_id:'589f80403f534993b49fd9fdd4d292ff'},
  properties:{
    ...extra,
    'สินค้า':{title:[{text:{content:f.name}}]},
    'ราคาเต็ม':{number:f.full},
    'ราคาลด':{number:f.sale},
    'ลิงก์Affiliate':{url:f.url||null},
    'หมวด':{select:{name:f.cat||'อื่นๆ'}},
    'สถานะ':{select:{name:'ใหม่'}}
  }
}}];

const f=$input.first().json;
const url=String(f['ลิงก์ Affiliate']||'').trim();
const name=String(f['สินค้า']||'').trim()||null;
const full=Number(f['ราคาเต็ม'])||null;
const sale=Number(f['ราคาลด'])||null;
const cat=String(f['หมวด']||'').trim()||null;
const source=!url?null:(/tiktok\.com/i.test(url)?'tiktok':(/lazada\.|lzd\.co/i.test(url)?'lazada':(/shopee\.|shp\.ee/i.test(url)?'shopee':null)));
const needParse=!(name&&sale);
return [{json:{url,name,full,sale,cat,source,needParse}}];

const info=$('Prep').first().json;
let og='';
try{
  const j=$input.first().json;
  const html=typeof j.data==='string'?j.data:(typeof j.body==='string'?j.body:'');
  const pick=re=>{const m=html.match(re);return m?m[1]:'';};
  og=pick(/property="og:title"[^>]*content="([^"]{0,300})"/)
   ||pick(/content="([^"]{0,300})"[^>]*property="og:title"/)
   ||pick(/<title[^>]*>([^<]{0,300})/);
  og=og.replace(/\s*\|\s*Shopee Thailand\s*$/,'').replace(/\s*[|-]\s*Lazada[^|]*$/i,'').trim();
}catch(e){}
const parts=[info.url];
if(info.name)parts.push('ชื่อจากผู้ใช้: '+info.name);
if(info.full)parts.push('ราคาเต็มจากผู้ใช้: '+info.full);
if(info.sale)parts.push('ราคาลดจากผู้ใช้: '+info.sale);
if(og)parts.push('og:title: '+og);
return [{json:{text:parts.join('\n')}}];

const resp=$input.first().json;
let parsed={};
try{const t=(resp.content||[{}])[0].text||'';parsed=JSON.parse((t.match(/\{[\s\S]*\}/)||['{}'])[0]);}catch(e){}
const info=$('Prep').first().json;
const name=info.name||((parsed.name||'').trim()||null);
const full=info.full||Number(parsed.full_price)||null;
const sale=info.sale||Number(parsed.sale_price)||null;
const cats=['gadget','ความงาม','บ้าน','แฟชั่น','อาหาร','รถ','อื่นๆ'];
const cat=info.cat||(cats.includes(parsed.category)?parsed.category:'อื่นๆ');
const complete=!!name;
const props={
  'สินค้า':{title:[{text:{content:name||'(รอเติมชื่อ) ดีลใหม่'}}]},
  'ลิงก์Affiliate':{url:info.url},
  'หมวด':{select:{name:cat}},
  'สถานะ':{select:{name:complete?'ใหม่':'รอตรวจ'}}
};
if(full)props['ราคาเต็ม']={number:full};
if(sale)props['ราคาลด']={number:sale};
if(info.source)props['แหล่ง']={select:{name:info.source}};
return [{json:{parent:{database_id:'589f80403f534993b49fd9fdd4d292ff'},properties:props}}];
